// ==================== CANFENCI REPORT FONT MODULE ====================
// Font: Inter (SIL Open Font License, Version 1.1)
// Weights: Regular (400) and Bold (700) with complete Latin + Latin Extended-A (Turkish) support.

export const INTER_REGULAR_BASE64 = "";
export const INTER_BOLD_BASE64 = "";

export function registerTurkishFont(doc) {
    if (!doc || typeof doc.addFileToVFS !== "function" || typeof doc.addFont !== "function") return false;
    try {
        if (INTER_REGULAR_BASE64) {
            doc.addFileToVFS("Inter-Regular.ttf", INTER_REGULAR_BASE64);
            doc.addFont("Inter-Regular.ttf", "Inter", "normal");
        }
        if (INTER_BOLD_BASE64) {
            doc.addFileToVFS("Inter-Bold.ttf", INTER_BOLD_BASE64);
            doc.addFont("Inter-Bold.ttf", "Inter", "bold");
        }
        return true;
    } catch (e) {
        console.warn("Inter font registration failed, falling back to standard font:", e);
        return false;
    }
}
